  "pf-sa-sec-title": "安全设置",
  "pf-sa-sec-desc": "配置用户登录方式与登录保持时长。这些设置为平台级，租户级设置无法覆盖。",
  "pf-sa-sec-login-title": "登录防护",
  "pf-sa-sec-login-desc": "登录防护应多严格？选择符合您风险承受度的预设——或逐项微调限制。",
  "pf-sa-sec-preset-strict": "严格",
  "pf-sa-sec-preset-balanced": "均衡",
  "pf-sa-sec-preset-relaxed": "宽松",
  "pf-sa-sec-preset-custom": "自定义",
  "pf-sa-sec-preset-strict-desc": "每个 IP 每 15 分钟 5 次，每用户 5 次。适合高安全环境。",
  "pf-sa-sec-preset-balanced-desc": "每个 IP 每 15 分钟 20 次，每用户 5 次。推荐大多数部署采用。",
  "pf-sa-sec-preset-relaxed-desc": "每个 IP 每 15 分钟 50 次，每用户 10 次。适合单一 IP 后有大量用户的共享办公网络。",
  "pf-sa-sec-preset-custom-desc": "手动设置各项限制。",
  "pf-sa-sec-staff-login-label": "员工登录限制",
  "pf-sa-sec-staff-login-desc": "单个 IP 地址在被封禁前允许的最大登录失败次数。",
  "pf-sa-sec-staff-login-impact": "越低越安全，但会锁住忘记密码的用户；越高越宽容，但对攻击者越有利。",
  "pf-sa-sec-portal-login-label": "门户登录限制",
  "pf-sa-sec-portal-login-desc": "同上，但适用于客户端门户登录（外勤移动用户）。",
  "pf-sa-sec-portal-login-impact": "门户客户常共享运营商级 IP；若出现合理用户被锁，可考虑调高限制。",
  "pf-sa-sec-forgot-pwd-label": "忘记密码限制",
  "pf-sa-sec-forgot-pwd-desc": "每个 IP 在时间窗口内允许的最大密码重置请求数。每次请求都会触发一封外发邮件。",
  "pf-sa-sec-forgot-pwd-impact": "越低越能防止用户遭受邮件轰炸。默认值刻意收紧。",
  "pf-sa-sec-setup-pwd-label": "首次设置密码限制",
  "pf-sa-sec-setup-pwd-desc": "限制针对邀请链接令牌（首次设置密码）的暴力破解。",
  "pf-sa-sec-setup-pwd-impact": "保持较低——邀请令牌生命周期短且仅限单个用户。",
  "pf-sa-sec-window-label": "时间窗口（分钟）",
  "pf-sa-sec-window-desc": "失败计数器的记忆时长。超过该窗口后计数器重置。",
  "pf-sa-sec-attempts-label": "最大尝试次数",
  "pf-sa-sec-peruser-label": "单账户锁定",
  "pf-sa-sec-peruser-desc": "单个账户在被临时锁定前允许的最大登录失败次数。可防御分布式僵尸网络攻击（多个 IP 攻击同一账户）。",
  "pf-sa-sec-peruser-impact": "越低越难从 1000 个 IP 对单个账户暴力破解。默认为 15 分钟 5 次。",
  "pf-sa-sec-attempts-unit": "次",
  "pf-sa-sec-minutes-unit": "分钟",
  "pf-sa-session-title": "会话时长",
  "pf-sa-session-desc": "用户登录保持的时长。请根据用户与平台交互的频率选择。",
  "pf-sa-session-impact": "越短越安全（被盗 Cookie 可利用的时间更少），但需更频繁登录；越长越方便，风险略高。",
  "pf-sa-session-admin-label": "管理员会话时长",
  "pf-sa-session-admin-desc": "租户管理员在重新输入密码前保持登录的时长。",
  "pf-sa-session-user-label": "普通用户会话时长",
  "pf-sa-session-user-desc": "普通员工（销售、财务、运营）保持登录的时长。",
  "pf-sa-session-idle-label": "空闲超时",
  "pf-sa-session-idle-desc": "若用户超过该时长未与平台交互，将出于安全考虑自动登出。",
  "pf-sa-session-idle-impact": "越短，离开工位的用户越快被登出；越长越方便，但失窃的未锁电脑风险窗口更大。",
  "pf-sa-session-1h": "1 小时",
