  "pf-sa-2fa-title": "双因素认证（2FA）",
  "pf-sa-2fa-desc": "双因素认证按用户逐一启用。每位用户需在自己的安全设置中开启。超级管理员登录时始终绕过双因素认证。",
  "pf-sa-2fa-info": "要对特定用户强制双因素认证，请编辑该用户并开启“启用 TOTP”。要在全平台强制执行，请在创建用户时于各角色的默认配置中开启。",
  "pf-sa-2fa-learn-more": "了解双因素认证的设置 →",
  "pf-sa-pwd-title": "密码要求",
  "pf-sa-pwd-desc": "所有新密码必须遵守的规则。现有密码不会追溯校验。",
  "pf-sa-pwd-min-length-label": "密码最小长度",
  "pf-sa-pwd-min-length-desc": "用户可设置的最短密码长度。不足者将在注册 / 重置 / 修改时被拒绝。",
  "pf-sa-pwd-min-length-impact": "GDPR / SOC2 最佳实践为不少于 8 位；NIST 800-63B 建议在启用多因素认证时不少于 8 位。",
  "pf-sa-pwd-req-upper-label": "要求包含大写字母",
  "pf-sa-pwd-req-upper-desc": "密码必须至少包含一个 A–Z。",
  "pf-sa-pwd-req-lower-label": "要求包含小写字母",
  "pf-sa-pwd-req-lower-desc": "密码必须至少包含一个 a–z。",
  "pf-sa-pwd-req-num-label": "要求包含数字",
  "pf-sa-pwd-req-num-desc": "密码必须至少包含一个 0–9。",
  "pf-sa-pwd-req-sym-label": "要求包含符号",
  "pf-sa-pwd-req-sym-desc": "密码必须至少包含一个符号（!@#$…）。",
  "pf-sa-pwd-req-sym-impact": "默认关闭——符号在移动端键盘上输入不便（门户客户）。",
  "pf-sa-pwd-expiry-label": "密码有效期（天）",
  "pf-sa-pwd-expiry-desc": "强制用户每 N 天更换密码。0 = 永不过期。",
  "pf-sa-pwd-expiry-impact": "SOC2 体系通常要求 90 天。NIST 现行指南倾向于不设有效期并启用多因素认证。请依据您的合规体系选择。",
  "pf-sa-pwd-history-label": "密码历史",
  "pf-sa-pwd-history-desc": "禁止复用最近 N 个密码。0 = 不检查历史。",
  "pf-sa-pwd-history-impact": "防止用户在两个密码间来回切换。默认 3。",
  "pf-sa-csrf-title": "跨站请求伪造（CSRF）防护",
  "pf-sa-csrf-desc": "平台始终在每个会更改状态的请求（POST/PUT/PATCH/DELETE）上校验 Origin 头。这是安全基线，无法关闭。",
  "pf-sa-csrf-cookie-label": "Cookie SameSite 策略",
  "pf-sa-csrf-cookie-value": "Lax（固定）",
  "pf-sa-csrf-cookie-desc": "浏览器 Cookie 仅在同站请求中携带（顶层导航除外）。这是安全的默认值，已硬编码。",
  "pf-sa-ac-title": "访问控制",
  "pf-sa-ac-desc": "谁可以在哪个租户做什么。角色覆盖、职责分离与功能开关均在此管理。",
  "pf-sa-ac-roles-title": "按租户的角色覆盖",
  "pf-sa-ac-roles-desc": "为特定角色授予或拒绝权限，可限定单个租户或全平台。拒绝优先于授予——请谨慎使用，优先使用显式的用户级权限。",
  "pf-sa-ac-sod-title": "职责分离矩阵",
  "pf-sa-ac-sod-desc": "防止单个用户同时持有可组合成舞弊路径的两项权限。“阻止”会在编辑用户时直接拒绝授予；“警告”仅记录违规。",
  "pf-sa-ac-catalog-title": "权限目录",
  "pf-sa-ac-catalog-desc": "RBAC 判定器识别的全部权限的权威列表。",
  "pf-sa-ac-flags-title": "按租户的功能开关",
  "pf-sa-ac-flags-desc": "按租户切换模块与 Beta 功能。找到租户后即可开关。",
  "pf-sa-dp-title": "数据保护",
  "pf-sa-dp-desc": "敏感数据如何加密、保存多久，以及用户如何行使 GDPR 权利。",
  "pf-sa-dp-vault-title": "保险库密钥管理",
  "pf-sa-dp-vault-desc": "用于静态保护机密的加密密钥。轮换时将使用当前密钥重新加密所有保险库条目。",
  "pf-sa-dp-encrypted-title": "字段加密目录",
  "pf-sa-dp-encrypted-desc": "以下字段已静态加密。列表为只读——新增字段需要发版部署。",
  "pf-sa-dp-retention-title": "数据保留策略",
  "pf-sa-dp-retention-desc": "平台在删除或匿名化个人信息前保留的时长。由每小时定时任务执行。保留规则的唯一权威来源在代码中——此表仅用于展示与审计。",
  "pf-sa-dp-gdpr-title": "GDPR 设置",
  "pf-sa-dp-gdpr-desc": "删除权级联、用户发起的数据导出与泄露通知追踪的开关。DPO 联系邮箱将展示在隐私政策中。",
  "pf-sa-dp-gdpr-erasure-label": "删除权（GDPR 第 17 条）",
  "pf-sa-dp-gdpr-erasure-desc": "移除用户时，匿名化其审计日志中的个人信息并级联删除其记录。",
  "pf-sa-dp-gdpr-export-label": "数据导出（GDPR 第 20 条）",
  "pf-sa-dp-gdpr-export-desc": "允许用户申请导出其本人数据的 CSV。为防滥用可关闭。",
  "pf-sa-dp-gdpr-breach-label": "泄露通知追踪（GDPR 第 33 条）",
  "pf-sa-dp-gdpr-breach-desc": "创建“泄露”类型事件时，自动计算 72 小时通知期限。",
  "pf-sa-dp-gdpr-dpo-label": "数据保护官（DPO）邮箱",
  "pf-sa-dp-gdpr-dpo-desc": "显示在隐私政策中，并作为泄露通知邮件的回复地址。",
  "pf-sa-dp-gdpr-residency-label": "数据驻留地",
  "pf-sa-dp-gdpr-residency-desc": "显示在隐私政策中——个人信息存储所在的地理区域。",
  "pf-sa-mon-title": "监控与告警",
  "pf-sa-mon-desc": "平台关注什么、如何呈现异常，以及出问题时通知谁。",
  "pf-sa-mon-sentry-title": "Sentry 错误监控",
  "pf-sa-mon-sentry-desc": "Sentry DSN 配置读取自环境变量（SENTRY_DSN、NEXT_PUBLIC_SENTRY_DSN）。下方状态仅作运维展示、只读——修改需重新部署。",
  "pf-sa-mon-sentry-status-label": "状态",
  "pf-sa-mon-sentry-env-label": "环境",
  "pf-sa-mon-sentry-rate-label": "采样率",
  "pf-sa-mon-sentry-rate-desc": "Sentry 记录的请求比例。通过 SENTRY_TRACES_SAMPLE_RATE 环境变量配置。",
  "pf-sa-mon-webhook-title": "安全事件 Webhook",
  "pf-sa-mon-webhook-desc": "平台级 Webhook，在重大安全事件（登录锁定、职责分离违规、保险库轮换、角色变更）时接收 POST 通知。",
  "pf-sa-mon-webhook-enabled-label": "启用 Webhook",
  "pf-sa-mon-webhook-enabled-desc": "关闭时不发送任何通知。设置好 URL 后再开启。",
  "pf-sa-mon-webhook-url-label": "Webhook URL",
  "pf-sa-mon-webhook-url-desc": "接受 POST application/json 的 HTTPS 端点。",
  "pf-sa-mon-webhook-payload-label": "包含原始载荷",
  "pf-sa-mon-webhook-payload-desc": "关 = 发送摘要（仅事件类型 + ID）；开 = 发送完整审计行。",
  "pf-sa-mon-anomaly-title": "异常检测阈值",
  "pf-sa-mon-anomaly-desc": "当 APM 缓冲区或登录历史超出以下任一阈值时，性能工作台与系统健康页将呈现告警。",
  "pf-sa-mon-anomaly-resp-label": "平均响应时间（ms）",
  "pf-sa-mon-anomaly-resp-desc": "持续高于此值将触发告警。默认 2000ms = 2 秒。",
  "pf-sa-mon-anomaly-errrate-label": "错误率（%）",
  "pf-sa-mon-anomaly-errrate-desc": "5xx 响应占比高于此值将触发告警。默认 5%。",
  "pf-sa-mon-anomaly-slow-label": "慢请求数",
  "pf-sa-mon-anomaly-slow-desc": "缓冲区内超过 2 秒的请求数达到该值即触发告警。",
  "pf-sa-mon-anomaly-login-label": "每小时登录失败次数",
  "pf-sa-mon-anomaly-login-desc": "单个 IP 每小时登录失败次数达到该值即触发安全告警。",
  "pf-sa-mon-routing-title": "告警路由",
  "pf-sa-mon-routing-desc": "将告警类型映射到收件邮箱。触发对应告警时通知收件人。",
  "pf-sa-inc-title": "事件响应",
  "pf-sa-inc-desc": "追踪安全事件，按响应手册处置，并满足 GDPR 泄露通知期限。",
  "pf-sa-inc-kpi-total": "事件总数",
